INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_SIPRWEB', 'AMBIENTE', '(OBBLIGATORIO) Indica il tipo di ambiente di protocollo che si intende utilizzare, TEST o PRODUZIONE, prende come valori T = Ambiente di Test, P = Ambiente di Produzione. Se si intende cambiare ambiente, oltre a questo parametro, vanno comunque modificati anche gli altri parametri (URL) presenti in questo modulo. Si è deciso di introdurre questo parametro in quanto i namespace dei wsdl dei webservice sono diversi in base al tipo di ambiente invocato, creando quindi la necessità di creare due classi proxy (una di Test e una di Produzione appunto) per ogni webservice presente in questo tipo di protocollo, il valore presente indicherà al componente, che si occupa della gestione del protocollo, di invocare la classe giusta in base all''esigenza del momento. Ad esempio il namespace presente sul wsdl di test del webservice dei TipiDocumento è - http://SIPrWeb/WebService.nsf/TipoDocService.wsdl - mentre per quello di produzione è - http://sipr/WebService.nsf/TipoDocService.wsdl - IMPORTANTE: questo parametro è obbligatorio, se non valorizzato sarà sollevata un''eccezione.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'URL', 'Endpoint del web service di INSIEL MERCATO, va inserito l''indirizzo http completo del wsdl. Il dato è ovviamente obbligatorio, per l''ambiente di test si può invocare l''url http://demo.insielmercato.it/protocollo-ws/services/protocolloService?wsdl');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'USERNAME', 'Valore obbligatorio, fa parte, con il parametro PASSWORD, al login al webservice, indica con quale username bisogna collegarsi al web service.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'PASSWORD', 'Valore obbligatorio, fa parte, con il parametro USERNAME, al login al webservice, indica con quale password bisogna collegarsi al web service.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'MODALITA_SEQUENZA', 'In base a quanto indicato dai fornitori del software (INSIEL MERCATO) valorizzare questo parametro solamente in base al codice proprio della sequenza: 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'ESCLUDI_CLASSIFICA', 'Questo parametro indica se deve essere considerata la classifica o meno, indicare 1 se si desidera escludere la classifica, 0 o non presente se si desidera inviare la classifica. Questo parametro è stato inserito perchè il dato non è specificato come obbligatorio dal web service, mentre è obbligatorio per noi, è quindi necessario configurare comunque la classifica a livello di backoffice (può andare bene anche un punto o un trattino) al fine di superare la nostra validazione interna che, come detto, rende obbligatorio questo dato. Successivamente, il componente incaricato di adattare i dati per il web service interrogherà questo parametro inviando la classifica o meno al web service di protocollazione.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'USA_WS_CLASSIFICHE', 'Indica se per il recupero delle classifiche, sull''albero degli interventi, debba essere usato il web service messo a disposizione da insiel mercato (valore = 1) oppure no (valore 0, vuoto o non presente). E'' stato deciso di inserire questo parametro in quanto recuperare le classifiche da web service potrebbe essere macchinoso rendendo la pagina del dettaglio degli interventi molto lenta se i dati dovessero essere molti come in ambiente di test. Oltre tutto i dati (sempre che siano tanti quanti l''ambiente di test) potrebbero creare una lunga lista difficilmente leggibile dagli utenti. In ultimo, se dovesso essere modificati i codici, questi non sarebbero più direttamente visibili sul campo Classifica nel dettaglio degli interventi in quanto non più presenti nella lista.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('CART', 'WSCALL_TIMEOUT', 'Indicare con un valore intero il timeout per la chiamata ai WS di CART.INTEGRATIONMANAGER. Con il valore viene impostata la chiamata a port.setTimeout(valore). Se non impostato prende il valore di timeout predefinito nella libreria CART (120.000 ms)');
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('SIT_BARI', 'Contiene i parametri di configurazione per l''integrazione con il sistema SIT utilizzato nell''installazione di Bari');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('SIT_BARI', 'COD_ENTE', 'Identificativo dell''installazione utilizzato dal SIT. Se lasciato vuoto o non presente verrà utilizzato il valore di default 01');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('SIT_BARI', 'REQUEST_FROM', 'Identificativo dell''applicazione che effettua la richiesta verso il sit. se non presente o lasciato vuoto verrà utilizzato il valore di default "Sigepro"');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('SIT_BARI', 'TIPO_INDIRIZZO_CERCATO', 'Non so a cosa serva, per bari va impostato a "c". Se lasciato vuoto o non presente verrà utilizzato il valore di default "c"');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('SIT_BARI', 'WS_URL_VALIDAZIONE_CIVICO', 'Url del web service da utilizzare per invocare il servizio di validazione civico. Nell''installazione di Bari l''indirizzo è "http://sit.comba.comune.bari.it:80/ServiziToponomastica/services/RicercaCivicoEPPort". Se lasciato vuoto verrà utilizzato il valore "http://sit.comba.comune.bari.it:80/ServiziToponomastica/services/RicercaCivicoEPPort"');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_ATTIVO', 'MEZZO_DEFAULT', 'Indica il mezzo di default da passare al web service. Questo parametro è stato creato per consentire il passaggio dell''elemento riferito a -A MEZZO DI- associato ai mittenti (protocollo in entrata) o ai destinatari (protocollo in uscita) dove i web service lo consentano (ad esempio IRIDE). Se valorizzato, viene proposto di default nella maschera di protocollazione, nel dropdown riguardante i mezzi dei mittenti / destinatari, e se lo stesso valore è presente nella tabella PROTOCOLLO_MEZZI. Viene inviato al web service anche quando la protocollazione è automatica, quindi proveniente da un frontoffice o dal backoffice se impostata la configurazione di protocollazione automatica. NB. se la tabella PROTOCOLLO_MEZZI è vuota il drop down mezzi, nella maschera di protocollazione, non viene visualizzato, ignorando quindi il valore di questo parametro.' );
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_ATTIVO', 'MODALITA_TRASMISSIONE_DEFAULT', 'Indica la modalita di trasmissione di default da passare al web service, un esempio di dati può essere: PER CONOSCENZA, FORMA DIRETTA.... Questo parametro è stato creato per consentire il passaggio dell''elemento riferito a -TRASMESSO PER- associato ai mittenti (protocollo in entrata) o ai destinatari (protocollo in uscita) dove i web service lo consentano (ad esempio INSIEL). Se valorizzato, viene proposto di default nella maschera di protocollazione nel dropdown riguardante la modalità di trasmissione dei mittenti / destinatari, e se lo stesso valore è presente nella tabella PROTOCOLLO_MODALITAINVIO. Viene inviato al web service anche quando la protocollazione è automatica, quindi proveniente da un frontoffice o dal backoffice se impostata la configurazione di protocollazione automatica. NB. se la tabella PROTOCOLLO_MODALITAINVIO è vuota il drop down trasmesso per, nella maschera di protocollazione, non viene visualizzato, ignorando quindi il valore di questo parametro.');
INSERT INTO verticalizzazionibase(modulo, descrizione) VALUES('PROTOCOLLO_HALLEY','E'' il protocollo gestito dalla ditta Halley Informatica, in teoria, questo protocollo, dovrebbe essere standard docarea, in realtà non lo è in quanto il metodo inserimento descritto dal wsdl è diverso da quello descritto sulle specifiche docarea (è presente un parametro in più), quindi è stato necessario creare una verticalizzazione e relativi parametri uguali a quelli della verticalizzazione PROTOCOLLO_DOCAREA. Un esempio di wsdl si trova sull''ambiente di test di Halley, http://213.82.177.135:4080/HalleySuapDOCAREA/suap/suap.php?wsdl'); 
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','OPERATORE','(Obbligatorio) Username di autenticazione al web service del protocollo Halley, è il parametro username che viene passato al web method Login. Deve essere fornito dal fornitore del protocollo'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','URL','(Obbligatorio) End point del web service per invocare i servizi, ad esempio per il protocollo halley l''ambiente di test è presente su http://213.82.177.135:4080/HalleySuapDOCAREA/suap/suap.php?wsdl');
insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','PASSWORD','Password di autenticazione al web service del protocollo Halley, è il parametro password che viene passato al web method Login. Deve essere fornito dal fornitore del protocollo'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','CODICEENTE','Codice Ente, questo parametro va ad aggiungersi a username e password e serve per l''autenticazione al web service del protocollo Halley, è il parametro codiceente che viene passato al web method Login. Deve essere fornito dal fornitore del protocollo'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','INVIA_ALL_MOV_AVVIO','(Facoltativo) Se valorizzato a 1 va a cercare in automatico, solamente durante la protocollazione da istanza, gli allegati caricati nel movimento di avvio dell''istanza stessa, se esistono questi vengono inviati al protocollo HALLEY.Se valorizzato con valore diverso da 1 o non valorizzato la funzionalità appena descritta non sarà svolta.'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','INVIA_SEGNATURA','(Facoltativo) Se valorizzato a 1 consente, in fase di protocollazione istanza o movimento da backoffice, di inviare il file segnatura.xml che sarebbe il file che viene inviato al web service per eseguire la protocollazione; se valorizzato a 0 o non valorizzato non esegue nessuna funzionalità.'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','CODICE_AOO','(Facoltativo) E'' il codice dell''Area Organizzativa Omogenea, va fornito dagli amministratori del protocollo. In precedenza veniva passato un parametro fisso con valore = ''AOO'' è stato modificato in quanto in alcuni casi (ad esempio Piacenza e Asp Roma) veniva richiesto un valore diverso. Sulle specifiche HALLEY (che sono le stesse docarea) viene descritto come: viene inizializzato con un valore che identifica l''ambito dell''applicazione.Ad esempio questo codice potrebbe essere utilizzato,per individuare i messaggi provenienti dal portale.Ovviamente si puo’ scegliere come nel caso a) di usare una codifica del tipo P_X dove X e’ il nome dell’applicazione chiamante.Questo valore viene inserito nel file segnatura.xml dentro Intestazione-->Identificatore-->CodiceAOO e dentro Intestazione -->Classifica -->CodiceAOO Se non valorizzato il parametro prenderà il valore di AOO'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','TIPO_DOCUMENTO_ALLEGATO','(Facoltativo) Specificare il valore del tipo documento allegato ossia quei documenti allegati al protocollo escluso quello principale. Se non valorizzato prenderà il valore = ''Allegato'' che era il valore fisso che veniva passato in precedenza. Viene valorizzato nel file segnatura.xml dentro Intestazione --> Descrizione --> Documento --> TipoDocumento successivamente a quello principale.'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','TIPO_DOCUMENTO_PRINCIPALE','(Facoltativo) Specificare il valore del tipo documento principale. ossia quel documento principale o di richiesta del protocollo. Se non valorizzato prenderà il valore = ''Principale'' che era il valore fisso che veniva passato in precedenza. E'' stato parametrizzato perchè a Piacenza viene richiesto un valore specifico che è ''TRAS''. Viene valorizzato nel file segnatura.xml dentro Intestazione --> Descrizione --> Documento --> TipoDocumento'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','APPLICATIVO_PROTOCOLLO','(Facoltativo) Indica il nome dell''applicativo del protocollo, questa voce sarà inserita dentro il file segnatura.xml dentro l''attributo -nome- di <ApplicativoProtocollo/>. NB. Se lasciato vuoto o non attivato prenderà il valore inserito dentro il parametro CODICEENTE'); insert into verticalizzazioniparametribase(modulo, parametro, descrizione) values('PROTOCOLLO_HALLEY','UO','(Facoltativo) Indica l''ufficio di smistamento del protocollo HALLEY, questa voce sarà inserita dentro il file segnatura.xml dentro il nodo <ApplicativoProtocollo> valorizzando un nuovo parametro con nome -uo-. E'' facoltativo ma il protocollo GS4 di ADS (Piacenza) lo richiede necessariamente.');
