INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCPRO', 'MODALITA_TRASMISSIONE_ARRIVO','Questo parametro è utilizzato per i protocolli in arrivo del Protocollo DOCPRO, a differenza di quelli in partenza, non è necessario scatenare l''invio di una mail, ma è comunque consigliato usare un parametro da passare al protocollo, ad esempio al Comune di Empoli passare il valore PORTALE'); 
INSERT INTO verticalizzazionibase(modulo, descrizione) VALUES('PROTOCOLLO_DOCER', 'Abilita il sistema di protocollazione STANDARD DOCER creato dalla Regione Emilia Romagna per le integrazioni con i vari sistemi di protocollo presenti nella regione. E'' uno standard, alla stregua di DocArea, ed è principalmente un gestore documentale in grado anche di trattare l''argomento della protocollazione, che poi è quello che interessa questa verticalizzazione, che deve essere abilitata per integrarsi con i sistemi che utilizzano lo Standard DocEr'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE VALUES ('WSANAGRAFE','URL_RICERCA_PF','URL completo del componente WS Anagrafe per la ricerca di una persona Fisica, se presente andrà a sovrascrivere quello di default che punta al componente doNet. Es. http://<ip-servert>:<port>/webapp/services/name_services?wsdl (http://devel9:8080/nla-pdd-ri/services/anagrafe?wsdl)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE VALUES ('WSANAGRAFE','URL_RICERCA_PG','URL completo del componente WS Anagrafe per la ricerca di una persona Giuridica, se presente andrà a sovrascrivere quello di default che punta al componente doNet. Es. http://<ip-servert>:<port>/webapp/services/name_services?wsdl (http://devel9:8080/nla-pdd-ri/services/anagrafe?wsdl)');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'URL_LOGIN', 'Per effettuare operazioni con un protocollo standard docer è necessario prima di tutto autenticarsi al web service, il sistema standard docer ha un web service apposito creato per gestire solo l''autenticazione, dentro questo parametro va indicato, appunto, l''end point del servizio che gestisce il Login');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'URL_GESTIONE_DOCS', 'Il sistema standard docer ha un web service apposito creato per gestire solo la gestione documentale, dentro questo parametro va indicato, appunto, l''end point del servizio della gestione documentale');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'URL_PROTOCOLLAZIONE', 'Il sistema standard docer ha un web service apposito creato per gestire solo il sistema di protocollazione, dentro questo parametro va indicato, appunto, l''end point del servizio che gestisce la protocollazione');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'URL_FASCICOLAZIONE', 'Il sistema standard docer ha un web service apposito creato per gestire solo la fascicolazione, dentro questo parametro va indicato, appunto, l''end point del servizio che gestisce la fascicolazione');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'USERNAME', 'Username riferito all''autenticazione al web service');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'PASSWORD', 'Password riferita all''autenticazione al web service');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'CODICE_ENTE', 'Parametro aggiuntivo all''autenticazione riferita al web service, per loggarsi al web service di login è necessario che sia presente, oltre che username e password, anche anche il parametro Codice Ente');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'APPLICAZIONE', 'Parametro aggiuntivo all''autenticazione riferita al web service, per loggarsi al web service di login è necessario che sia presente, oltre che username e password, anche anche il parametro Applicazione, in sostanza sarebbe l''identificativo dell''applicazione dalla quale l''utente sta effettuando l''autenticazione');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'CODICE_AOO', 'Codice dell''Area Organizzativa Omogenea, questo parametro viene passato al web service della gestione documentale, in particolare questo dato è una proprietà del documento che viene inviato al sistema documentale');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'ALLEGATO_PRINCIPALE', 'Costante che indica come deve essere chiamato il documento principale che viene passato al sistema documentale, in vbg il documento principale è il primo della lista. I documenti possono assumere i seguenti valori: PRINCIPALE, ALLEGATO, ANNOTAZIONE, ANNESSO, da specifiche al momento va inserito il valore PRINCIPALE. Da considerare inoltre, sempre al momento, è possibile protocollare solamente un documento alla volta.');
INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_DOCER', 'UO', 'Unità organizzativa, è riferita all''unità di smistamento in fase di protocollazione, questo dato non è obbligatorio.'); 
