INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES ('STC','NOTIFICHE_AUT_ATTESA_MILLIS','Indica il tempo di attesa in millisecondi per l''attivazione del componente che esegue le notifica automatiche in maniera asincrona. Se non specificato o non valido di default è 20000 (20 secondi)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES  ('STC','TIMEOUT_CONNESSIONE','Indica il tempo di attesa in millisecondi per la connessione del nodo di backoffice con il nodo STC. Se non specificato o non valido di default è 120000 (120 secondi)') ;
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) VALUES  ('STC','TIMEOUT_RISPOSTA','Indica il tempo di attesa in millisecondi per la risposta del nodo di STC alla chiamata del nodo di backoffice. Se non specificato o non valido di default è 120000 (120 secondi)') ;
